{
  "name": "Heraeus Cytomat自动微孔板培养存储系统",
  "name_en": "Heraeus Cytomat automated microplate incubator",
  "manufacturer": "Heraeus",
  "description": "这是一种用于自动化实验流程的微孔板培养与存储设备，带有温度控制、振荡和传送工位，可在内部板架中存放微孔板，并通过舱门与装载托盘完成进出板。常用于细胞培养、样品孵育以及与机器人联用的高通量实验流程。",
  "description_en": "An automated microplate incubator and storage unit for laboratory automation workflows. It provides temperature control, shaking, and a transfer/loading station to move plates between internal racks and external handlers. It is used for microplate incubation, storage, and robotic high-throughput laboratory workflows.",
  "tag_hints": [
    "automated microplate incubation",
    "plate hotel",
    "temperature control",
    "microplate shaking",
    "robotic plate transfer",
    "transfer station",
    "high-throughput screening"
  ],
  "actions": [
    {
      "action_name": "auto-close_door",
      "description": "关闭培养箱舱门。",
      "description_en": "Close the incubator door."
    },
    {
      "action_name": "auto-fetch_plate_to_loading_tray",
      "description": "将微孔板从内部存储位取到装载/传送工位。",
      "description_en": "Fetch a microplate from internal storage to the loading/transfer station."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化培养箱及其内部传板机构。",
      "description_en": "Initialize the incubator and its internal plate-handling mechanism."
    },
    {
      "action_name": "auto-open_door",
      "description": "打开培养箱舱门。",
      "description_en": "Open the incubator door."
    },
    {
      "action_name": "auto-read_plate_detection_xfer",
      "description": "读取传送工位上的微孔板检测状态。",
      "description_en": "Read the plate-detection status at the transfer station."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备当前配置或状态信息。",
      "description_en": "Export the current device configuration or state information."
    },
    {
      "action_name": "auto-set_racks",
      "description": "设置内部板架或堆栈配置。",
      "description_en": "Define the internal rack or stacker configuration."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温度。",
      "description_en": "set temperature"
    },
    {
      "action_name": "auto-setup",
      "description": "建立通信并使设备进入可操作状态。",
      "description_en": "Establish communication and place the device into an operational state."
    },
    {
      "action_name": "auto-start_shaking",
      "description": "开始对微孔板进行振荡。",
      "description_en": "Start shaking the microplates."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备运行。",
      "description_en": "Stop device operation."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-take_in_plate",
      "description": "将微孔板从传送工位送入指定存储位。",
      "description_en": "Move a microplate from the transfer station into the specified storage location."
    },
    {
      "action_name": "auto-wait_for_transfer_station",
      "description": "等待传送工位达到指定占用状态。",
      "description_en": "Wait for the transfer station to reach the requested occupied state."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取温度。",
      "description_en": "get temperature"
    },
    {
      "action_name": "auto-deserialize",
      "description": "从已保存的信息恢复设备配置或状态。",
      "description_en": "Restore the device configuration or state from saved information."
    }
  ]
}

